(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const catalog=window.SANTA_CATALOG, sizes={1:[1041,824],2:[1082,688],3:[1054,635],4:[1047,677],5:[1061,649],6:[1097,681],7:[1085,680],8:[1076,645],9:[757,733]};
const categories=[['all','Todos'],['3','S/ 3 · US$ 1'],['5','S/ 5 · US$ 2'],['largos','Grandes aventuras'],['cortos','Para los pequeños'],['cumple','Cumpleaños'],['llamadas','Videollamadas'],['empresas','Empresas'],['entrega','Video y tarjeta QR']];
const shortFields=['Nombre del niño o niña','Edad o fecha de nacimiento','Ciudad y país donde vive','Foto del niño o niña'];
const longFields=[...shortFields,'Su tema favorito','Comentario de Santa','Nombres de familiares y amigos','Un logro o momento destacado','Fotos de familiares, amigos o remitente','Tu relación con el niño o niña','Regalo deseado','Un esfuerzo que quieras reconocer','Mensaje de la lista de los buenos'];
let category='all', limit=12, currentStory=null, returnFocus=null;
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const price=s=>$('#market').value==='peru'?`S/ ${s.pen}`:`US$ ${s.usd}`;
function artwork(story){let [w,h]=sizes[story.image],[x,y,cw,ch]=story.rect;return `background-image:url('assets/catalogo/escenas-${story.image}.webp');background-size:${w/cw*100}% ${h/ch*100}%;background-position:${x/(w-cw)*100}% ${y/(h-ch)*100}%;`;}
function selectOptions(select,items,placeholder){select.replaceChildren();if(placeholder)select.append(new Option(placeholder,''));for(const group of [...new Set(items.map(x=>x.group))]){const groupItems=items.filter(x=>x.group===group);const optgroup=document.createElement('optgroup');optgroup.label=groupItems[0].groupLabel;groupItems.forEach(x=>optgroup.append(new Option(`${x.title} · ${price(x)}`,x.id)));select.append(optgroup);}}
function renderCatalog(){const query=normalize($('#catalog-search').value);const match=catalog.filter(s=>(category==='all'||category===s.group||String(s.pen)===category)&&normalize(s.title).includes(query));const shown=match.slice(0,limit);const parent=$('#catalog-results');parent.replaceChildren();for(const group of [...new Set(shown.map(x=>x.group))]){const section=document.createElement('section');section.className='catalog-group';const items=shown.filter(x=>x.group===group);const heading=document.createElement('h3');heading.textContent=items[0].groupLabel;const grid=document.createElement('div');grid.className='catalog-grid';for(const story of items){const button=document.createElement('button');button.type='button';button.className='catalog-card';button.setAttribute('aria-label',`Ver y personalizar ${story.title}`);button.setAttribute('aria-haspopup','dialog');const art=document.createElement('span');art.className='catalog-art';art.style.cssText=artwork(story);art.setAttribute('aria-hidden','true');const tag=document.createElement('span');tag.className='catalog-card-tag';tag.textContent=price(story);const copy=document.createElement('span');copy.className='catalog-card-copy';const title=document.createElement('strong');title.textContent=story.title;const sub=document.createElement('small');sub.textContent=`${story.kind} · ${story.duration}`;copy.append(title,sub);button.append(art,tag,copy);button.addEventListener('click',()=>openStory(story,button));grid.append(button);}section.append(heading,grid);parent.append(section);}$('#catalog-count').textContent=`${shown.length} de ${match.length} saludos · ${catalog.length} en la lista completa`;$('#catalog-more').hidden=shown.length>=match.length;$('#catalog-empty').hidden=!!match.length;$$('.filters button').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category));});}
function openStory(story,trigger){currentStory=story;returnFocus=trigger;$('#dialog-title').textContent=story.title;$('#dialog-category').textContent=story.groupLabel;$('#dialog-description').textContent=story.group==='llamadas'?'Un mensaje cercano de Santa con su nombre y sus detalles, en formato de llamada. Coordinamos contigo la preparación por WhatsApp.':story.description;$('#dialog-duration').textContent=`◷ ${story.duration} · S/ ${story.pen} o US$ ${story.usd}`;let poster=$('.dialog-poster');const details=story.sourceKey==='sendero'?['detalle-sendero.webp',838,328]:story.sourceKey==='tesoro'?['detalle-tesoro.webp',814,330]:null;poster.classList.toggle('clean',!!details);poster.style.cssText=details?`background-image:url('assets/catalogo/${details[0]}');background-size:100% ${details[1]/details[2]*100}%;background-position:top center;`:artwork(story);poster.setAttribute('aria-label',`Escenario de referencia de ${story.title}`);$('#dialog-group').hidden=!story.premium;$('#dialog-fields').replaceChildren(...(story.premium?longFields:shortFields).map(text=>{let li=document.createElement('li');li.textContent=text;return li;}));$('#greeting-dialog').showModal();$('#greeting-dialog').scrollTop=0;document.body.classList.add('modal-open');}
function updateForm(preserve=true){const previous=preserve?$('#theme').value:'';const plan=$('#plan').value;selectOptions($('#theme'),catalog.filter(x=>String(x.pen)===plan),'Elige el nombre del saludo…');if(catalog.some(x=>x.id===previous&&String(x.pen)===plan))$('#theme').value=previous;$('#advanced-fields').hidden=plan!=='5';$('#advanced-fields').disabled=plan!=='5';updateSummary();clearOrder();}
function updateSummary(){const story=catalog.find(s=>s.id===$('#theme').value);const pen=Number($('#plan').value);$('#order-total').textContent=$('#market').value==='peru'?`S/ ${pen}`:`US$ ${pen===5?2:1}`;$('#order-summary').replaceChildren();let strong=document.createElement('strong');strong.textContent=story?story.title:'Elige el nombre de tu saludo';let p=document.createElement('p');p.textContent=`${pen===5?'5 minutos a más · Formulario completo':'1 a 3 minutos · Nombre, edad, ciudad y foto'}`;$('#order-summary').append(strong,p);$('#qr-order').hidden=story?.group!=='entrega';clearOrder();}
function clearOrder(){$('#form-status').hidden=true;$('#order-ready').hidden=true;$('#order-message').value='';$('#order-copy-status').textContent='';}
function chooseStory(story){$('#plan').value=String(story.pen);updateForm(false);$('#theme').value=story.id;updateSummary();$('#pedido').scrollIntoView({behavior:'instant'});$('#child-name').focus({preventScroll:true});}
for(const [id,label] of categories){let b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.category=id;b.addEventListener('click',()=>{category=id;limit=12;renderCatalog();});$('.filters').append(b);}
selectOptions($('#catalog-select'),catalog,'Ver los 54 saludos…');$('#catalog-select').addEventListener('change',e=>{let s=catalog.find(x=>x.id===e.target.value);if(s)openStory(s,e.target);});$('#catalog-search').addEventListener('input',()=>{limit=12;renderCatalog();});$('#catalog-more').addEventListener('click',()=>{limit+=12;renderCatalog();});$('.dialog-close').addEventListener('click',()=>$('#greeting-dialog').close());$('#greeting-dialog').addEventListener('click',e=>{if(e.target===$('#greeting-dialog'))$('#greeting-dialog').close();});$('#greeting-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');returnFocus?.focus({preventScroll:true});});$('#choose-theme').addEventListener('click',()=>{const s=currentStory;returnFocus=null;$('#greeting-dialog').close();chooseStory(s);});$('#market').addEventListener('change',()=>{selectOptions($('#catalog-select'),catalog,'Ver los 54 saludos…');updateForm();renderCatalog();});$('#plan').addEventListener('change',()=>updateForm(false));$('#theme').addEventListener('change',updateSummary);$('#greeting-form').addEventListener('input',clearOrder);
for(const [inputId,previewId] of [['child-photo','order-photos'],['family-photos','family-previews']]){let urls=[];$('#'+inputId).addEventListener('change',()=>{urls.forEach(URL.revokeObjectURL);urls=[];let p=$('#'+previewId);p.replaceChildren();for(const file of [...$('#'+inputId).files].slice(0,12)){if(!file.type.startsWith('image/'))continue;let im=document.createElement('img');im.src=URL.createObjectURL(file);urls.push(im.src);im.alt='Foto seleccionada: '+file.name;p.append(im);}});}
$('#greeting-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);const story=catalog.find(s=>s.id===d.get('theme'));if(!story)return;const lines=['¡Hola, La aldea de Santa! Quiero pedir un saludo personalizado.','',`Saludo: ${story.title}`,`Formato: ${story.kind}`,`Duración: ${story.duration}`,`Precio: ${price(story)}`,`Tarifa: ${d.get('market')==='peru'?'Perú':'Otros países'}`,'',`Nombre: ${String(d.get('childName')).trim()}`,`Edad: ${d.get('age')} años`,`Ciudad y país: ${String(d.get('location')).trim()}`];if(story.premium){for(const [key,label] of [['birthdate','Nacimiento'],['relation','Relación'],['favorite','Tema favorito'],['family','Familiares y amigos'],['achievement','Logro o momento especial'],['gift','Regalo deseado'],['effort','Esfuerzo que reconocer'],['message','Comentario de Santa'],['verdict','Mensaje de la lista']]){if(d.get(key))lines.push(`${label}: ${String(d.get(key)).trim()}`);}}if(story.group==='entrega')lines.push('Incluye tarjeta con código QR al video.');lines.push('','Enviaré por este chat las fotos que quiero incluir. Quiero coordinar el pago y la entrega.');$('#order-message').value=lines.join('\n');$('#fallback-link').href='https://w.app/cubasai';$('#order-ready').hidden=false;$('#form-status').textContent='Tu pedido está listo. Cópialo y abre WhatsApp con el botón de abajo.';$('#form-status').hidden=false;$('#copy-order').focus();});
$('#copy-order').addEventListener('click',async()=>{const message=$('#order-message').value;if(!message)return;try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(message);$('#order-copy-status').textContent='Pedido copiado. Toca Abrir WhatsApp y pégalo en el chat.';}catch{const area=$('#order-message');area.focus();area.select();$('#order-copy-status').textContent='El pedido está seleccionado. Mantén pulsado y elige Copiar, o usa Ctrl+C en PC; después abre WhatsApp.';}});
updateForm();renderCatalog();
})();
